      "workReturn": "7 \u2013 10 \u0623\u064A\u0627\u0645 (\u0628\u0639\u062F \u0641\u0643 \u0627\u0644\u063A\u0631\u0632 \u0627\u0644\u062F\u0642\u064A\u0642\u0629)",
      "scar": "\u0645\u062E\u0641\u064A\u0629 \u062A\u0645\u0627\u0645\u0627\u064B \u062F\u0627\u062E\u0644 \u062B\u0646\u064A\u0629 \u0627\u0644\u062C\u0641\u0646 \u0627\u0644\u0639\u0644\u0648\u064A \u0623\u0648 \u0623\u0633\u0641\u0644 \u062E\u0637 \u0627\u0644\u0631\u0645\u0648\u0634/\u0645\u0646 \u0627\u0644\u062F\u0627\u062E\u0644",
      "finalResult": "\u062A\u062D\u0633\u0646 \u0648\u0627\u0636\u062D \u062E\u0644\u0627\u0644 3 \u0623\u0633\u0627\u0628\u064A\u0639 \u0648\u0627\u0633\u062A\u0642\u0631\u0627\u0631 \u0643\u0627\u0645\u0644 \u062E\u0644\u0627\u0644 2 \u2013 3 \u0623\u0634\u0647\u0631",
      "stayDays": 7,
      "sportReturn": "\u0628\u0639\u062F 2 \u2013 3 \u0623\u0633\u0627\u0628\u064A\u0639",
      "rationale": "\u0625\u062C\u0631\u0627\u0621 \u062F\u0642\u064A\u0642 \u0648\u0633\u0631\u064A\u0639 \u0627\u0644\u062A\u0639\u0627\u0641\u064A \u064A\u0632\u064A\u0644 \u0641\u0627\u0626\u0636 \u0627\u0644\u062C\u0644\u062F \u0627\u0644\u0645\u0631\u0647\u0642 \u0641\u064A \u0627\u0644\u062C\u0641\u0646 \u0627\u0644\u0639\u0644\u0648\u064A \u0648\u064A\u0639\u064A\u062F \u062A\u0648\u0632\u064A\u0639 \u0623\u0648 \u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u062C\u064A\u0648\u0628 \u0627\u0644\u062F\u0647\u0646\u064A\u0629 \u0623\u0633\u0641\u0644 \u0627\u0644\u0639\u064A\u0646\u060C \u0645\u0645\u0627 \u064A\u0639\u064A\u062F \u0644\u0644\u0639\u064A\u0646 \u0627\u062A\u0633\u0627\u0639\u0647\u0627 \u0648\u0646\u0636\u0627\u0631\u062A\u0647\u0627 \u0627\u0644\u0637\u0628\u064A\u0639\u064A\u0629 \u062F\u0648\u0646 \u062A\u063A\u064A\u064A\u0631 \u0634\u062E\u0635\u064A\u0629 \u0627\u0644\u0645\u0644\u0627\u0645\u062D.",
      "realityCheck": "\u062A\u062C\u0645\u064A\u0644 \u0627\u0644\u062C\u0641\u0648\u0646 \u064A\u0639\u0627\u0644\u062C \u0627\u0644\u062C\u0644\u062F \u0627\u0644\u0632\u0627\u0626\u062F \u0648\u0627\u0644\u0627\u0646\u062A\u0641\u0627\u062E\u0627\u062A \u0627\u0644\u062F\u0647\u0646\u064A\u0629 \u0628\u0641\u0627\u0639\u0644\u064A\u0629 \u0645\u0630\u0647\u0644\u0629\u060C \u0628\u064A\u0646\u0645\u0627 \u0627\u0644\u0647\u0627\u0644\u0627\u062A \u0627\u0644\u0635\u0628\u063A\u064A\u0629 \u0623\u0648 \u0627\u0644\u063A\u0648\u0631 \u0627\u0644\u0634\u062F\u064A\u062F \u0642\u062F \u062A\u062D\u062A\u0627\u062C \u062F\u0645\u062C \u0646\u0627\u0646\u0648\u0641\u0627\u062A \u0623\u0648 \u0639\u0646\u0627\u064A\u0629 \u062A\u0643\u0645\u064A\u0644\u064A\u0629 \u0644\u0644\u0628\u0634\u0631\u0629.",
      "altLabel": "\u0628\u0631\u0648\u062A\u0648\u0643\u0648\u0644 \u0645\u0643\u0645\u0644 \u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0639\u064A\u0646",
      "altTitle": "\u062D\u0642\u0646 \u0627\u0644\u0646\u0627\u0646\u0648\u0641\u0627\u062A (Nano-Fat) \u0623\u0648 \u0627\u0644\u0628\u0648\u062A\u0648\u0643\u0633 \u0627\u0644\u062F\u0642\u064A\u0642",
      "altDesc": "\u064A\u062D\u0633\u0651\u0646 \u062C\u0648\u062F\u0629 \u062C\u0644\u062F \u0627\u0644\u062C\u0641\u0646 \u0627\u0644\u0633\u0641\u0644\u064A \u0648\u064A\u062E\u0641\u0641 \u0627\u0644\u062A\u062C\u0627\u0639\u064A\u062F \u0627\u0644\u062A\u0639\u0628\u064A\u0631\u064A\u0629 \u062D\u0648\u0644 \u0627\u0644\u0639\u064A\u0646 \u0628\u062A\u0646\u0627\u063A\u0645 \u0637\u0628\u064A\u0639\u064A."
