      "finalResult": "\u0627\u0633\u062A\u0642\u0631\u0627\u0631 \u062E\u0644\u0627\u0644 2 \u2013 3 \u0623\u0634\u0647\u0631 \u0645\u0639 \u062A\u062D\u0633\u0646 \u0645\u0633\u062A\u0645\u0631 \u0644\u062C\u0648\u062F\u0629 \u0627\u0644\u062C\u0644\u062F",
      "stayDays": 5,
      "sportReturn": "\u0628\u0639\u062F 2 \u0623\u0633\u0628\u0648\u0639",
      "rationale": "\u064A\u0633\u062A\u0639\u064A\u062F \u0627\u0644\u0627\u0645\u062A\u0644\u0627\u0621 \u0627\u0644\u0634\u0628\u0627\u0628\u064A \u0627\u0644\u0637\u0628\u064A\u0639\u064A \u0641\u064A \u0627\u0644\u062E\u062F\u064A\u0646 \u0648\u0645\u062D\u064A\u0637 \u0627\u0644\u0639\u064A\u0646 \u0628\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u062E\u0644\u0627\u064A\u0627\u0643 \u0627\u0644\u0630\u0627\u062A\u064A\u0629 (Micro-Fat)\u060C \u0628\u064A\u0646\u0645\u0627 \u062A\u0639\u0645\u0644 \u0627\u0644\u062E\u0644\u0627\u064A\u0627 \u0627\u0644\u062A\u062C\u062F\u064A\u062F\u064A\u0629 \u0641\u064A \u0627\u0644\u0640 Nano-Fat \u0639\u0644\u0649 \u062A\u062D\u0633\u064A\u0646 \u0645\u0644\u0645\u0633 \u0627\u0644\u062C\u0644\u062F \u0648\u0627\u0644\u0647\u0627\u0644\u0627\u062A \u0628\u0644\u0645\u0633\u0629 \u0646\u0627\u0639\u0645\u0629 \u063A\u064A\u0631 \u0645\u0635\u0637\u0646\u0639\u0629.",
      "realityCheck": "\u0627\u0644\u062A\u0648\u0631\u0645 \u0627\u0644\u0645\u0628\u062F\u0626\u064A \u0623\u0648\u0644 \u0623\u0633\u0628\u0648\u0639 \u064A\u062C\u0639\u0644 \u0627\u0644\u0648\u062C\u0647 \u064A\u0628\u062F\u0648 \u0623\u0643\u062B\u0631 \u0627\u0645\u062A\u0644\u0627\u0621\u064B \u0645\u0645\u0627 \u0633\u064A\u0633\u062A\u0642\u0631 \u0639\u0644\u064A\u0647\u060C \u0648\u062C\u0632\u0621 \u0645\u0646 \u0627\u0644\u062F\u0647\u0648\u0646 \u064A\u064F\u0645\u062A\u0635 \u0637\u0628\u064A\u0639\u064A\u0627\u064B\u061B \u0644\u0630\u0627 \u064A\u064F\u062D\u0633\u0628 \u0627\u0644\u062D\u0642\u0646 \u0628\u062F\u0642\u0629 \u0644\u062A\u062D\u0642\u064A\u0642 \u0646\u062A\u064A\u062C\u0629 \u0647\u0627\u062F\u0626\u0629 \u0648\u0645\u062A\u0648\u0627\u0632\u0646\u0629.",
      "altLabel": "\u0628\u062F\u064A\u0644 \u063A\u064A\u0631 \u062C\u0631\u0627\u062D\u064A \u0641\u0648\u0631\u064A",
      "altTitle": "\u0645\u062D\u0641\u0632\u0627\u062A \u0627\u0644\u0643\u0648\u0644\u0627\u062C\u064A\u0646 (Olidia) \u0645\u0639 \u0639\u0646\u0627\u064A\u0629 \u0627\u0644\u0628\u0634\u0631\u0629 \u0627\u0644\u062A\u062C\u062F\u064A\u062F\u064A\u0629",
      "altDesc": "\u0645\u0646\u0627\u0633\u0628\u0629 \u0625\u0630\u0627 \u0644\u0645 \u062A\u062A\u0648\u0641\u0631 \u062F\u0647\u0648\u0646 \u0643\u0627\u0641\u064A\u0629 \u0644\u0644\u0634\u0641\u0637 \u0623\u0648 \u0625\u0630\u0627 \u0643\u0646\u062A \u062A\u0641\u0636\u0644 \u0625\u062C\u0631\u0627\u0621\u064B \u0633\u0631\u064A\u0639\u0627\u064B \u062F\u0627\u062E\u0644 \u0627\u0644\u0639\u064A\u0627\u062F\u0629."
