      "scar": "\u062F\u0627\u062E\u0644\u064A\u0629 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0623\u0648 \u0634\u0642 \u062F\u0642\u064A\u0642 \u062C\u062F\u0627\u064B \u0623\u0633\u0641\u0644 \u0627\u0644\u0623\u0646\u0641 \u064A\u062A\u0644\u0627\u0634\u0649 \u062A\u062F\u0631\u064A\u062C\u064A\u0627\u064B",
      "finalResult": "80% \u062E\u0644\u0627\u0644 3 \u0623\u0634\u0647\u0631\u060C \u0648\u0627\u0644\u062A\u062D\u062F\u064A\u062F \u0627\u0644\u0646\u0647\u0627\u0626\u064A \u0627\u0644\u062F\u0642\u064A\u0642 \u062E\u0644\u0627\u0644 6 \u2013 12 \u0634\u0647\u0631\u0627\u064B",
      "stayDays": 8,
      "sportReturn": "\u0643\u0627\u0631\u062F\u064A\u0648 3 \u0623\u0633\u0627\u0628\u064A\u0639 \u2022 \u0623\u0648\u0632\u0627\u0646 6 \u0623\u0633\u0627\u0628\u064A\u0639 \u2022 \u0631\u064A\u0627\u0636\u0627\u062A \u0627\u062D\u062A\u0643\u0627\u0643\u064A\u0629 3 \u0623\u0634\u0647\u0631",
      "rationale": "\u064A\u0631\u0643\u0632 \u062A\u062C\u0645\u064A\u0644 \u0627\u0644\u0623\u0646\u0641 \u0627\u0644\u062A\u062D\u0641\u0638\u064A \u0639\u0644\u0649 \u0627\u0644\u062D\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u062F\u0639\u0627\u0626\u0645 \u0627\u0644\u0637\u0628\u064A\u0639\u064A\u0629 \u0644\u062C\u0633\u0631 \u0627\u0644\u0623\u0646\u0641 \u0648\u062A\u0642\u0644\u064A\u0644 \u0627\u0644\u0631\u0636\u0651 \u0627\u0644\u062C\u0631\u0627\u062D\u064A\u060C \u0645\u0639 \u0625\u0645\u0643\u0627\u0646\u064A\u0629 \u0625\u0635\u0644\u0627\u062D \u0627\u0646\u062D\u0631\u0627\u0641 \u0627\u0644\u062D\u0627\u062C\u0632 \u0627\u0644\u0623\u0646\u0641\u064A \u0648\u062A\u0636\u062E\u0645 \u0627\u0644\u063A\u0636\u0627\u0631\u064A\u0641 \u0641\u064A \u0646\u0641\u0633 \u0627\u0644\u0639\u0645\u0644\u064A\u0629 \u0644\u0636\u0645\u0627\u0646 \u062A\u0646\u0641\u0633 \u0633\u0644\u0633 \u0648\u0634\u0643\u0644 \u0645\u062A\u0646\u0627\u063A\u0645 \u0645\u0639 \u0645\u0644\u0627\u0645\u062D \u0627\u0644\u0648\u062C\u0647.",
      "realityCheck": "\u062A\u062C\u0645\u064A\u0644 \u0627\u0644\u0623\u0646\u0641 \u064A\u062A\u0637\u0644\u0628 \u0635\u0628\u0631\u0627\u064B\u061B \u0623\u0631\u0646\u0628\u0629 \u0627\u0644\u0623\u0646\u0641 \u0647\u064A \u0622\u062E\u0631 \u062C\u0632\u0621 \u064A\u0632\u0648\u0644 \u0645\u0646\u0647 \u0627\u0644\u062A\u0648\u0631\u0645 \u0627\u0644\u062F\u0642\u064A\u0642\u060C \u062E\u0635\u0648\u0635\u0627\u064B \u0641\u064A \u062D\u0627\u0644\u0627\u062A \u0627\u0644\u062C\u0644\u062F \u0627\u0644\u0633\u0645\u064A\u0643\u060C \u0644\u0630\u0627 \u0644\u0627 \u064A\u064F\u062D\u0643\u0645 \u0639\u0644\u0649 \u0627\u0644\u0646\u062A\u064A\u062C\u0629 \u0627\u0644\u0646\u0647\u0627\u0626\u064A\u0629 \u0639\u0646\u062F \u0631\u0641\u0639 \u0627\u0644\u062C\u0628\u064A\u0631\u0629.",
      "altLabel": "\u0644\u0644\u0639\u064A\u0648\u0628 \u0627\u0644\u0637\u0641\u064A\u0641\u0629 \u062C\u062F\u0627\u064B \u0641\u064A \u0627\u0644\u062C\u0633\u0631 \u0641\u0642\u0637",
      "altTitle": "\u062A\u0642\u064A\u064A\u0645 \u062F\u0642\u0629 \u0627\u0644\u062A\u0634\u0631\u064A\u062D \u0642\u0628\u0644 \u0627\u0644\u062A\u0641\u0643\u064A\u0631 \u0628\u0623\u064A \u0625\u062C\u0631\u0627\u0621 \u063A\u064A\u0631 \u062C\u0631\u0627\u062D\u064A",
      "altDesc": "\u0627\u0644\u0641\u064A\u0644\u0631 \u0627\u0644\u0623\u0646\u0641\u064A \u0645\u062D\u062F\u0648\u062F \u0627\u0644\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0648\u0645\u0624\u0642\u062A \u0648\u0644\u0627 \u064A\u0635\u063A\u0631 \u062D\u062C\u0645 \u0627\u0644\u0623\u0646\u0641 \u0623\u0648 \u064A\u0639\u0627\u0644\u062C \u0627\u0644\u062A\u0646\u0641\u0633\u061B \u0627\u0644\u062C\u0631\u0627\u062D\u0629 \u0627\u0644\u062A\u062D\u0641\u0638\u064A\u0629 \u0647\u064A \u0627\u0644\u062D\u0644 \u0627\u0644\u062C\u0630\u0631\u064A \u0627\u0644\u0622\u0645\u0646."
