      "rationale": "\u0625\u062C\u0631\u0627\u0621 \u062F\u0642\u064A\u0642 \u064A\u0639\u064A\u062F \u062A\u0634\u0643\u064A\u0644 \u0637\u064A\u0627\u062A \u063A\u0636\u0631\u0648\u0641 \u0627\u0644\u0623\u0630\u0646 \u0648\u064A\u0642\u0644\u0644 \u0632\u0627\u0648\u064A\u0629 \u0627\u0644\u0628\u0631\u0648\u0632 \u0628\u062A\u0646\u0627\u0633\u0642 \u062A\u0627\u0645 \u0628\u064A\u0646 \u0627\u0644\u0623\u0630\u0646\u064A\u0646\u060C \u0645\u0645\u0627 \u064A\u0646\u0639\u0643\u0633 \u0641\u0648\u0631\u0627\u064B \u0639\u0644\u0649 \u0631\u0627\u062D\u0629 \u0627\u0644\u0645\u0638\u0647\u0631 \u0648\u0627\u0644\u062B\u0642\u0629 \u0628\u0627\u0644\u0646\u0641\u0633.",
      "realityCheck": "\u0627\u0644\u0627\u0644\u062A\u0632\u0627\u0645 \u0628\u0631\u0628\u0627\u0637 \u0627\u0644\u0631\u0623\u0633 \u0627\u0644\u0637\u0628\u064A \u0627\u0644\u0644\u0637\u064A\u0641 (\u062E\u0627\u0635\u0629 \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u0646\u0648\u0645 \u062E\u0644\u0627\u0644 \u0623\u0648\u0644 \u0623\u0633\u0627\u0628\u064A\u0639) \u0636\u0631\u0648\u0631\u064A \u0644\u062D\u0645\u0627\u064A\u0629 \u0627\u0644\u063A\u0636\u0631\u0648\u0641 \u0627\u0644\u0645\u0634\u0643\u0651\u0644 \u062D\u062F\u064A\u062B\u0627\u064B \u0645\u0646 \u0623\u064A \u0627\u0644\u062A\u0648\u0627\u0621 \u063A\u064A\u0631 \u0645\u0642\u0635\u0648\u062F.",
