      "t2Sec3T": "\u0627\u0644\u0625\u062C\u0631\u0627\u0621\u0627\u062A \u0627\u0644\u0645\u0633\u062A\u0647\u062F\u0641\u0629 \u0644\u0644\u0627\u0633\u062A\u0634\u0627\u0631\u0629",
      "t2Sec3S": "\u064A\u0645\u0643\u0646\u0643 \u0627\u062E\u062A\u064A\u0627\u0631 \u0625\u062C\u0631\u0627\u0621 \u0648\u0627\u062D\u062F \u0623\u0648 \u0623\u0643\u062B\u0631 \u0644\u0645\u0646\u0627\u0642\u0634\u062A\u0647 \u0641\u064A \u0627\u0644\u062C\u0644\u0633\u0629",
      "lblTimeline": "\u0627\u0644\u062A\u0648\u0642\u064A\u062A \u0627\u0644\u0645\u0633\u062A\u0647\u062F\u0641 \u0644\u0644\u0625\u062C\u0631\u0627\u0621",
      "t2Sec4T": "\u0627\u0644\u0641\u0631\u0632 \u0627\u0644\u0637\u0628\u064A \u0648\u0627\u0644\u0623\u0645\u0627\u0646 \u0627\u0644\u0633\u0631\u064A\u0639",
