      "t2Sec5T": "\u0623\u0647\u0645 \u0627\u0644\u0623\u0633\u0626\u0644\u0629 \u0627\u0644\u062A\u064A \u062A\u0648\u062F \u0637\u0631\u062D\u0647\u0627 \u0641\u064A \u0627\u0644\u0627\u0633\u062A\u0634\u0627\u0631\u0629",
      "t2Sec5S": "\u0627\u0636\u063A\u0637 \u0639\u0644\u0649 \u0623\u064A \u0633\u0624\u0627\u0644 \u0644\u0625\u0636\u0627\u0641\u062A\u0647 \u062A\u0644\u0642\u0627\u0626\u064A\u0627\u064B \u0625\u0644\u0649 \u0623\u062C\u0646\u062F\u0629 \u0645\u0643\u0627\u0644\u0645\u062A\u0643",
      "lblNotes": "\u0645\u0644\u0627\u062D\u0638\u0627\u062A \u0623\u0648 \u062A\u0641\u0627\u0635\u064A\u0644 \u0625\u0636\u0627\u0641\u064A\u0629 \u0644\u0644\u0637\u0628\u064A\u0628",
