      "t3Sec1T": "\u0627\u0644\u0632\u0648\u0627\u064A\u0627 \u0627\u0644\u0637\u0628\u064A\u0629 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629 \u0644\u0644\u062A\u0642\u064A\u064A\u0645",
