      "t3Sec2T": "\u0627\u0644\u0642\u0648\u0627\u0639\u062F \u0627\u0644\u0623\u0631\u0628\u0639 \u0627\u0644\u0630\u0647\u0628\u064A\u0629 \u0644\u0644\u062A\u0635\u0648\u064A\u0631 \u0627\u0644\u0637\u0628\u064A",
