  var FAQS = [
    {
      "arQ": "\u0647\u0644 \u0627\u0644\u0627\u0633\u062A\u0634\u0627\u0631\u0629 \u0648\u0627\u0644\u0635\u0648\u0631 \u0641\u064A \u0633\u0631\u0651\u064A\u0629 \u0637\u0628\u064A\u0629 \u062A\u0627\u0645\u0629\u061F",
      "enQ": "Are my video consultation and photos strictly confidential?",
      "arA": "\u062A\u062C\u0647\u064A\u0632 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0648\u0634\u0631\u064A\u0637 \u0627\u0644\u062E\u0635\u0648\u0635\u064A\u0629 \u064A\u062A\u0645 \u0645\u062D\u0644\u064A\u0627\u064B \u062F\u0627\u062E\u0644 \u0647\u0630\u0647 \u0627\u0644\u0635\u0641\u062D\u0629\u060C \u0648\u0644\u0627 \u062A\u064F\u0631\u0641\u0639 \u0627\u0644\u0635\u0648\u0631 \u062A\u0644\u0642\u0627\u0626\u064A\u0627\u064B. \u0639\u0646\u062F \u0641\u062A\u062D \u0648\u0627\u062A\u0633\u0627\u0628 \u0623\u0648 \u0645\u0646\u0635\u0629 \u0627\u0644\u0641\u064A\u062F\u064A\u0648\u060C \u062A\u0637\u0628\u0642 \u0633\u064A\u0627\u0633\u0629 \u062A\u0644\u0643 \u0627\u0644\u062E\u062F\u0645\u0629. \u0644\u0627 \u062A\u0631\u0633\u0644 \u0625\u0644\u0627 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062A \u0648\u0627\u0644\u0635\u0648\u0631 \u0627\u0644\u062A\u064A \u062A\u062E\u062A\u0627\u0631 \u0645\u0634\u0627\u0631\u0643\u062A\u0647\u0627 \u0645\u0639 \u0627\u0644\u0639\u064A\u0627\u062F\u0629.",
      "enA": "The intake and privacy-bar preview are prepared locally. Photos are not uploaded automatically. WhatsApp and the video platform have their own privacy policies. Share only the information you choose to send to the clinic."
    },
    {
      "arQ": "\u0647\u0644 \u064A\u0645\u0643\u0646\u0646\u064A \u0625\u0634\u0631\u0627\u0643 \u0645\u0631\u0627\u0641\u0642 \u0623\u0648 \u0641\u0631\u062F \u0645\u0646 \u0627\u0644\u0639\u0627\u0626\u0644\u0629 \u0641\u064A \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0629\u061F",
      "enQ": "May a partner or family member join the video call?",
      "arA": "\u0628\u0627\u0644\u062A\u0623\u0643\u064A\u062F\u060C \u0646\u0631\u062D\u0628 \u0628\u062D\u0636\u0648\u0631 \u0627\u0644\u0632\u0648\u062C \u0623\u0648 \u0623\u062D\u062F \u0623\u0641\u0631\u0627\u062F \u0627\u0644\u0623\u0633\u0631\u0629 \u0644\u0644\u0627\u0633\u062A\u0645\u0627\u0639 \u0644\u0644\u0634\u0631\u062D \u0627\u0644\u0637\u0628\u064A \u0648\u0637\u0631\u062D \u0627\u0644\u0623\u0633\u0626\u0644\u0629 \u062D\u0648\u0644 \u062E\u0637\u0629 \u0627\u0644\u062A\u0639\u0627\u0641\u064A \u0648\u0645\u0648\u0627\u0639\u064A\u062F \u0627\u0644\u0633\u0641\u0631.",
      "enA": "Yes, we warmly welcome a partner or family member to join the session and discuss recovery logistics and travel planning."
    },
    {
      "arQ": "\u0643\u064A\u0641 \u0623\u0633\u062A\u0643\u0645\u0644 \u0627\u0644\u062A\u0631\u062A\u064A\u0628\u0627\u062A \u0625\u0630\u0627 \u0642\u0631\u0631\u062A \u0627\u0644\u0633\u0641\u0631 \u0625\u0644\u0649 \u0627\u0644\u0642\u0627\u0647\u0631\u0629\u061F",
      "enQ": "How do we transition to Cairo surgical planning if I proceed?",
      "arA": "\u0641\u0648\u0631 \u0627\u062A\u0641\u0627\u0642\u0643 \u0639\u0644\u0649 \u0627\u0644\u062E\u0637\u0629 \u062E\u0644\u0627\u0644 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0629\u060C \u064A\u0631\u062A\u0651\u0628 \u0641\u0631\u064A\u0642 \u0627\u0644\u062A\u0646\u0633\u064A\u0642 \u0627\u0644\u062F\u0648\u0644\u064A \u0645\u0648\u0639\u062F \u0645\u0633\u062A\u0634\u0641\u0649 \u0627\u0644\u0646\u062E\u0628\u0629 \u0648\u0627\u0644\u062A\u062D\u0627\u0644\u064A\u0644 \u0648\u062A\u0646\u0633\u064A\u0642 \u0625\u0642\u0627\u0645\u0629 \u0627\u0644\u062A\u0639\u0627\u0641\u064A \u0627\u0644\u0645\u0641\u0636\u0644\u0629 \u0644\u062F\u064A\u0643 \u0641\u064A \u0627\u0644\u0642\u0627\u0647\u0631\u0629 \u0642\u0628\u0644 \u062D\u062C\u0632 \u062A\u0630\u0627\u0643\u0631 \u0627\u0644\u0637\u064A\u0631\u0627\u0646.",
      "enA": "Once you approve your surgical plan, our concierge desk locks your Class A hospital slot, pre-op labs, and luxury Cairo stay before you book flights."
    },
    {
      "arQ": "\u0645\u0627 \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u062A\u0642\u0646\u064A\u0627\u064B \u0642\u0628\u0644 \u0628\u062F\u0621 \u0645\u0643\u0627\u0644\u0645\u0629 \u0627\u0644\u0641\u064A\u062F\u064A\u0648\u061F",
      "enQ": "What technical setup is recommended before the call?",
      "arA": "\u0627\u062A\u0635\u0627\u0644 \u0625\u0646\u062A\u0631\u0646\u062A \u0645\u0633\u062A\u0642\u0631 \u0648\u0625\u0636\u0627\u0621\u0629 \u0623\u0645\u0627\u0645\u064A\u0629 \u062C\u064A\u062F\u0629 \u0641\u064A \u063A\u0631\u0641\u0629 \u0647\u0627\u062F\u0626\u0629\u060C \u0648\u062A\u062B\u0628\u064A\u062A \u0627\u0644\u0647\u0627\u062A\u0641 \u0641\u064A \u0645\u0633\u062A\u0648\u0649 \u0627\u0644\u0648\u062C\u0647 \u062D\u062A\u0649 \u064A\u062A\u0645\u0643\u0646 \u0627\u0644\u0637\u0628\u064A\u0628 \u0645\u0646 \u0627\u0644\u062A\u0642\u064A\u064A\u0645 \u0628\u0648\u0636\u0648\u062D.",
      "enA": "A quiet room with stable Wi-Fi, soft front lighting, and your phone positioned steadily at eye level for clear clinical assessment."
    }
  ];
